<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Page Not Found | IdeaForum</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --color-primary: #EB0028;
      --color-dark: #121212;
      --color-bg: #FFFFFF;
      --color-text-secondary: #696969;
      --color-link: #777777;
      --color-border: #E5E5E5;
      --color-divider: #E0E0E0;
      --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    }

    html, body {
      height: 100%;
    }

    body {
      font-family: var(--font-family);
      background-color: var(--color-bg);
      color: var(--color-dark);
      line-height: 1.6;
      display: flex;
      flex-direction: column;
      min-height: 100vh;
    }

    /* Main content wrapper */
    .main-content {
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 3rem 1.5rem;
      text-align: center;
    }

    /* Hero Logo */
    .logo {
      margin-bottom: 3rem;
    }

    .logo-wordmark {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0;
      font-size: 2rem;
      font-weight: 700;
      letter-spacing: -0.02em;
    }

    .logo-wordmark .logo-idea {
      color: var(--color-dark);
    }

    .logo-wordmark .logo-forum {
      color: var(--color-dark);
    }

    /* Dashed outline E for 404 concept */
    .logo-wordmark .logo-missing-e {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 1.4em;
      height: 1.1em;
      margin: 0 0.02em;
      border: 2px dashed var(--color-primary);
      border-radius: 3px;
      color: var(--color-primary);
      font-size: 1em;
      line-height: 1;
    }

    /* Error message section */
    .error-message {
      margin-bottom: 2.5rem;
    }

    .error-apology {
      font-size: 1.75rem;
      font-weight: 600;
      color: var(--color-dark);
      margin-bottom: 0.75rem;
    }

    .error-suggestion {
      font-size: 1rem;
      color: var(--color-text-secondary);
    }

    /* Search section */
    .search-section {
      width: 100%;
      max-width: 480px;
      margin-bottom: 3rem;
    }

    .search-form {
      display: flex;
      position: relative;
    }

    .search-input {
      width: 100%;
      padding: 0.875rem 3rem 0.875rem 1rem;
      font-family: var(--font-family);
      font-size: 1rem;
      color: var(--color-dark);
      background-color: var(--color-bg);
      border: 1px solid var(--color-border);
      border-radius: 8px;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
    }

    .search-input::placeholder {
      color: var(--color-text-secondary);
    }

    .search-input:focus {
      border-color: var(--color-primary);
      box-shadow: 0 0 0 3px rgba(235, 0, 40, 0.1);
    }

    .search-btn {
      position: absolute;
      right: 0.5rem;
      top: 50%;
      transform: translateY(-50%);
      width: 2.5rem;
      height: 2.5rem;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
      border: none;
      cursor: pointer;
      color: var(--color-text-secondary);
      transition: color 0.2s ease;
    }

    .search-btn:hover {
      color: var(--color-primary);
    }

    .search-btn svg {
      width: 1.25rem;
      height: 1.25rem;
    }

    /* Error code section */
    .error-code-section {
      width: 100%;
      max-width: 480px;
      margin-bottom: 2.5rem;
    }

    .error-code-bar {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 0.875rem 1.5rem;
      background-color: #F5F5F5;
      border-radius: 6px;
    }

    .error-code-text {
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--color-text-secondary);
      letter-spacing: 0.02em;
    }

    .error-divider {
      width: 100%;
      max-width: 480px;
      height: 1px;
      background-color: var(--color-divider);
      margin: 0 auto;
    }

    /* Next steps section */
    .next-steps {
      margin-top: 2rem;
    }

    .next-steps-heading {
      font-size: 1rem;
      font-weight: 600;
      color: var(--color-dark);
      margin-bottom: 1rem;
    }

    .next-steps-links {
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
      align-items: center;
    }

    .next-steps-link {
      font-size: 0.9375rem;
      color: var(--color-link);
      text-decoration: none;
      transition: color 0.2s ease;
      display: flex;
      align-items: center;
      gap: 0.25rem;
    }

    .next-steps-link:hover {
      color: var(--color-primary);
      text-decoration: underline;
    }

    .next-steps-link svg {
      width: 1rem;
      height: 1rem;
    }

    /* Cookie consent banner */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background-color: #F8F8F8;
      border-top: 1px solid var(--color-divider);
      padding: 1rem 1.5rem;
      z-index: 100;
      display: none;
    }

    .cookie-banner.visible {
      display: block;
    }

    .cookie-content {
      max-width: 900px;
      margin: 0 auto;
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
    }

    @media (min-width: 640px) {
      .cookie-content {
        flex-direction: row;
        align-items: center;
        justify-content: space-between;
        gap: 1.5rem;
      }
    }

    .cookie-message {
      font-size: 0.8125rem;
      color: var(--color-text-secondary);
      line-height: 1.5;
    }

    .cookie-message a {
      color: var(--color-link);
      text-decoration: underline;
    }

    .cookie-message a:hover {
      color: var(--color-primary);
    }

    .cookie-actions {
      display: flex;
      align-items: center;
      gap: 1rem;
      flex-shrink: 0;
    }

    .cookie-prefs-btn {
      font-family: var(--font-family);
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--color-dark);
      background-color: transparent;
      border: 1px solid var(--color-border);
      padding: 0.5rem 1rem;
      border-radius: 6px;
      cursor: pointer;
      transition: background-color 0.2s ease, border-color 0.2s ease;
    }

    .cookie-prefs-btn:hover {
      background-color: var(--color-bg);
      border-color: var(--color-dark);
    }

    /* Cookie preferences modal */
    .cookie-modal-overlay {
      position: fixed;
      inset: 0;
      background-color: rgba(0, 0, 0, 0.4);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 200;
      padding: 1.5rem;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.2s ease, visibility 0.2s ease;
    }

    .cookie-modal-overlay.open {
      opacity: 1;
      visibility: visible;
    }

    .cookie-modal {
      background-color: var(--color-bg);
      border-radius: 12px;
      width: 100%;
      max-width: 500px;
      max-height: 80vh;
      overflow-y: auto;
      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);
    }

    .cookie-modal-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 1.25rem 1.5rem;
      border-bottom: 1px solid var(--color-divider);
    }

    .cookie-modal-title {
      font-size: 1.125rem;
      font-weight: 600;
      color: var(--color-dark);
    }

    .cookie-modal-close {
      width: 2rem;
      height: 2rem;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
      border: none;
      cursor: pointer;
      color: var(--color-text-secondary);
      border-radius: 4px;
      transition: background-color 0.2s ease;
    }

    .cookie-modal-close:hover {
      background-color: #F0F0F0;
    }

    .cookie-modal-close svg {
      width: 1.25rem;
      height: 1.25rem;
    }

    .cookie-modal-body {
      padding: 1.5rem;
    }

    .cookie-category {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 0;
      border-bottom: 1px solid var(--color-divider);
    }

    .cookie-category:last-child {
      border-bottom: none;
    }

    .cookie-category-info {
      flex: 1;
    }

    .cookie-category-name {
      font-size: 0.9375rem;
      font-weight: 500;
      color: var(--color-dark);
      margin-bottom: 0.25rem;
    }

    .cookie-category-desc {
      font-size: 0.8125rem;
      color: var(--color-text-secondary);
      line-height: 1.5;
    }

    .cookie-toggle {
      position: relative;
      width: 44px;
      height: 24px;
      flex-shrink: 0;
    }

    .cookie-toggle input {
      opacity: 0;
      width: 0;
      height: 0;
    }

    .cookie-toggle-slider {
      position: absolute;
      cursor: pointer;
      inset: 0;
      background-color: #CCCCCC;
      border-radius: 24px;
      transition: background-color 0.2s ease;
    }

    .cookie-toggle-slider::before {
      content: '';
      position: absolute;
      height: 18px;
      width: 18px;
      left: 3px;
      bottom: 3px;
      background-color: white;
      border-radius: 50%;
      transition: transform 0.2s ease;
    }

    .cookie-toggle input:checked + .cookie-toggle-slider {
      background-color: var(--color-primary);
    }

    .cookie-toggle input:checked + .cookie-toggle-slider::before {
      transform: translateX(20px);
    }

    .cookie-modal-footer {
      padding: 1rem 1.5rem;
      border-top: 1px solid var(--color-divider);
      display: flex;
      justify-content: flex-end;
    }

    .cookie-save-btn {
      font-family: var(--font-family);
      font-size: 0.875rem;
      font-weight: 500;
      color: white;
      background-color: var(--color-primary);
      border: none;
      padding: 0.625rem 1.25rem;
      border-radius: 6px;
      cursor: pointer;
      transition: background-color 0.2s ease;
    }

    .cookie-save-btn:hover {
      background-color: #C7001F;
    }

    /* Responsive adjustments */
    @media (min-width: 640px) {
      .main-content {
        padding: 4rem 2rem;
      }

      .logo-wordmark {
        font-size: 2.5rem;
      }

      .error-apology {
        font-size: 2rem;
      }

      .next-steps-links {
        flex-direction: row;
        gap: 2rem;
      }
    }

    @media (min-width: 768px) {
      .main-content {
        padding: 5rem 2rem;
      }
    }
  </style>
</head>
