            <input type="checkbox" id="personalizationCookie">
            <span class="cookie-toggle-slider"></span>
          </label>
        </div>
        <div class="cookie-category">
          <div class="cookie-category-info">
            <div class="cookie-category-name">Advertising Cookies</div>
            <div class="cookie-category-desc">Used to deliver relevant advertisements and track campaign performance.</div>
          </div>
          <label class="cookie-toggle">
            <input type="checkbox" id="advertisingCookie">
            <span class="cookie-toggle-slider"></span>
          </label>
