      <div class="cookie-modal-footer">
        <button class="cookie-save-btn" id="saveCookiePrefs">Save Preferences</button>
      </div>
    </div>
  </div>

  <script>
    // Cookie preferences modal functionality
    const cookieBanner = document.getElementById('cookieBanner');
    const cookieModal = document.getElementById('cookieModal');
    const openCookiePrefsBtn = document.getElementById('openCookiePrefs');
    const closeCookieModalBtn = document.getElementById('closeCookieModal');
    const saveCookiePrefsBtn = document.getElementById('saveCookiePrefs');

    function openModal() {
      cookieModal.classList.add('open');
      document.body.style.overflow = 'hidden';
      closeCookieModalBtn.focus();
    }

    function closeModal() {
      cookieModal.classList.remove('open');
      document.body.style.overflow = '';
      openCookiePrefsBtn.focus();
    }

    function savePreferences() {
      // In a real implementation, this would save to localStorage or send to server
      const preferences = {
        analytics: document.getElementById('analyticsCookie').checked,
        personalization: document.getElementById('personalizationCookie').checked,
        advertising: document.getElementById('advertisingCookie').checked
      };
      console.log('Cookie preferences saved:', preferences);
      closeModal();
      // Hide banner after saving (simulating consent acceptance)
      cookieBanner.classList.remove('visible');
    }

    openCookiePrefsBtn.addEventListener('click', openModal);
    closeCookieModalBtn.addEventListener('click', closeModal);
    saveCookiePrefsBtn.addEventListener('click', savePreferences);

    // Close modal on overlay click
    cookieModal.addEventListener('click', function(e) {
      if (e.target === cookieModal) {
        closeModal();
      }
    });

    // Close modal on Escape key
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && cookieModal.classList.contains('open')) {
        closeModal();
      }
    });

